function viral_news_register_fonts() {
    return apply_filters('viral_news_regsiter_fonts', array(
        array(
            'label' => esc_html__('Default', 'viral-news'),
            'fonts' => viral_news_default_fonts()
        ),
        array(
            'label' => esc_html__('Standard Fonts', 'viral-news'),
            'fonts' => viral_news_standard_fonts()
        ),
        array(
            'label' => esc_html__('Google Fonts', 'viral-news'),
            'fonts' => viral_news_google_fonts()
        )
    ));
}

function viral_news_all_fonts() {
    $fonts = viral_news_register_fonts();
    $fonts_array = array();

    foreach ($fonts as $font) {
        $fonts_array += $font['fonts'];
    }

    return $fonts_array;
}
